"use client";

import type { EmailDocument } from "@/lib/email/document";
import type { ActivePanel } from "./editor-types";
import { BlockInspector } from "./block-inspector";
import { BlockPalette } from "./block-palette";
import { OptimizePanel } from "./optimize-panel";
import { SectionsPanel } from "./sections-panel";
import { StylesPanel } from "./styles-panel";
import type { EmailBlock } from "@/lib/email/document";

/** Left edge of the flyout = width of the icon nav rail. */
const NAV_WIDTH = 56;
const PANEL_WIDTH = 320;
/** Gap between the rail and the floating preview card (visual only — the hit
 *  area still spans it, so it isn't a hover dead zone). */
const PREVIEW_GAP_X = 12;
const PREVIEW_GAP_Y = 14;
const FLYOUT_TRANSITION =
  "top 260ms cubic-bezier(0.22,1,0.36,1), bottom 260ms cubic-bezier(0.22,1,0.36,1), " +
  "left 260ms cubic-bezier(0.22,1,0.36,1), border-radius 260ms ease, " +
  "box-shadow 260ms ease, opacity 180ms ease, transform 220ms cubic-bezier(0.22,1,0.36,1)";

interface SidePanelProps {
  /** Which panel's content to show (hover preview OR pinned). null = closed. */
  panel: ActivePanel;
  /** True while this is a hover preview (floating) rather than pinned (docked). */
  preview: boolean;
  /** Pin the currently-previewed panel — fired when the user clicks inside it. */
  onCommit: () => void;
  document: EmailDocument;
  selectedBlock: EmailBlock | undefined;
  onAdd: (type: EmailBlock["type"]) => void;
  onBack: () => void;
  onMoveUp: () => void;
  onMoveDown: () => void;
  onUpdateDocument: (updater: (current: EmailDocument) => EmailDocument) => void;
}

export function SidePanel({
  panel,
  preview,
  onCommit,
  document,
  selectedBlock,
  onAdd,
  onBack,
  onMoveUp,
  onMoveDown,
  onUpdateDocument,
}: SidePanelProps) {
  const open = panel !== null;
  const mode = !open ? "closed" : preview ? "preview" : "docked";

  const showPalette = panel === "blocks" && !selectedBlock;
  const showInspector = panel === "blocks" && !!selectedBlock;

  return (
    // Outer hit area: transparent, flush to the rail and full-height, spanning
    // the card AND its preview gap. The cursor never crosses a dead zone moving
    // from the rail to the floating card, so the hover never drops mid-move.
    <div
      onClick={onCommit}
      className="absolute"
      style={{
        left: NAV_WIDTH,
        top: 0,
        bottom: 0,
        width: PANEL_WIDTH + PREVIEW_GAP_X,
        pointerEvents: open ? "auto" : "none",
      }}
    >
      {/* Visible card. Docked: flush, full height, right corners rounded.
          Preview: inset by the gap on all sides, fully rounded, lifted shadow
          — clearly reads as a temporary floating preview until clicked. */}
      <div
        className="absolute flex flex-col bg-card"
        style={{
          width: PANEL_WIDTH,
          left: mode === "docked" ? 0 : PREVIEW_GAP_X,
          top: mode === "docked" ? 0 : PREVIEW_GAP_Y,
          bottom: mode === "docked" ? 0 : PREVIEW_GAP_Y,
          borderRadius: mode === "docked" ? "0 16px 16px 0" : 18,
          boxShadow:
            mode === "preview"
              ? "0 24px 70px rgba(0,0,0,0.22)"
              : mode === "docked"
              ? "4px 0 24px rgba(0,0,0,0.07)"
              : "none",
          opacity: open ? 1 : 0,
          transform: open ? "translateX(0)" : "translateX(-14px)",
          overflow: "hidden",
          transition: FLYOUT_TRANSITION,
        }}
      >
        {/* Keyed so swapping panels (Blocks → Sections) cross-fades cleanly. */}
        <div
          key={panel ?? "none"}
          className="flex h-full flex-col duration-200 animate-in fade-in-0"
        >
          {showPalette && <BlockPalette onAdd={onAdd} />}

          {showInspector && selectedBlock && (
            <BlockInspector
              block={selectedBlock}
              document={document}
              onBack={onBack}
              onMoveUp={onMoveUp}
              onMoveDown={onMoveDown}
              onUpdateDocument={onUpdateDocument}
            />
          )}

          {panel === "sections" && <SectionsPanel />}

          {panel === "styles" && (
            <StylesPanel document={document} onUpdateDocument={onUpdateDocument} />
          )}

          {panel === "optimize" && <OptimizePanel document={document} />}
        </div>
      </div>
    </div>
  );
}

"use client";

import { HugeiconsIcon } from "@hugeicons/react";
import { CheckmarkCircle01Icon } from "@hugeicons/core-free-icons";
import { cn } from "@/lib/utils";
import type { EmailDocument } from "@/lib/email/document";

export function OptimizePanel({ document }: { document: EmailDocument }) {
  const checks = [
    { label: "Add a subject line",             done: Boolean(document.subject) },
    { label: "Add preview text",               done: Boolean(document.settings.previewText) },
    { label: "Add at least one content block", done: document.blocks.length > 0 },
    { label: "Include a footer / unsubscribe", done: document.blocks.some((b) => b.type === "footer") },
    { label: "Keep email under 100 KB",        done: true },
  ];
  const done = checks.filter((c) => c.done).length;

  return (
    <div className="flex flex-col overflow-auto">
      <div className="border-b px-4 py-3">
        <p className="text-sm font-semibold">Optimize</p>
        <p className="mt-0.5 text-xs text-muted-foreground">
          {done}/{checks.length} checks passed
        </p>
      </div>

      <div className="mx-4 mt-3 h-1.5 overflow-hidden rounded-full bg-muted">
        <div
          className="h-full rounded-full bg-emerald-500 transition-[width] duration-500"
          style={{ width: `${(done / checks.length) * 100}%` }}
        />
      </div>

      <div className="flex flex-col gap-0.5 p-4">
        {checks.map((check) => (
          <div key={check.label} className="flex items-start gap-3 rounded-lg px-2 py-2.5">
            <HugeiconsIcon
              icon={CheckmarkCircle01Icon}
              strokeWidth={check.done ? 2.5 : 1.5}
              className={cn(
                "mt-0.5 size-4 shrink-0 transition-colors",
                check.done ? "text-emerald-500" : "text-muted-foreground/30",
              )}
            />
            <span
              className={cn(
                "text-xs leading-snug",
                check.done ? "text-muted-foreground line-through" : "text-foreground",
              )}
            >
              {check.label}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

import { HugeiconsIcon } from "@hugeicons/react";
import { Settings02Icon } from "@hugeicons/core-free-icons";
import { Button } from "@/components/ui/button";
import { Field, FieldLabel } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";
import { Textarea } from "@/components/ui/textarea";
import {
  touchDocument,
  type EmailDocument,
  type EmailDocumentSettings,
} from "@/lib/email/document";

export function GlobalSettingsSheet({
  document,
  onUpdateDocument,
}: {
  document: EmailDocument;
  onUpdateDocument: (updater: (current: EmailDocument) => EmailDocument) => void;
}) {
  const setSetting = <K extends keyof EmailDocumentSettings>(
    key: K,
    value: EmailDocumentSettings[K],
  ) => {
    onUpdateDocument((c) =>
      touchDocument({ ...c, settings: { ...c.settings, [key]: value } }),
    );
  };

  return (
    <Sheet>
      <SheetTrigger asChild>
        <Button variant="outline" size="sm">
          <HugeiconsIcon icon={Settings02Icon} strokeWidth={2} data-icon="inline-start" />
          Settings
        </Button>
      </SheetTrigger>
      <SheetContent className="w-[380px] sm:max-w-[380px]">
        <SheetHeader>
          <SheetTitle>Campaign settings</SheetTitle>
          <SheetDescription>Subject line, sender info, and metadata.</SheetDescription>
        </SheetHeader>
        <ScrollArea className="min-h-0 flex-1 px-6 pb-6">
          <div className="flex flex-col gap-4 pt-2">
            <Field>
              <FieldLabel htmlFor="doc-name">Campaign name</FieldLabel>
              <Input
                id="doc-name"
                value={document.name}
                onChange={(e) =>
                  onUpdateDocument((c) => touchDocument({ ...c, name: e.target.value }))
                }
              />
            </Field>
            <Field>
              <FieldLabel htmlFor="subject">Subject line</FieldLabel>
              <Input
                id="subject"
                value={document.subject}
                placeholder="e.g. Your June newsletter"
                onChange={(e) =>
                  onUpdateDocument((c) => touchDocument({ ...c, subject: e.target.value }))
                }
              />
            </Field>
            <Field>
              <FieldLabel htmlFor="from-name">From name</FieldLabel>
              <Input
                id="from-name"
                value={document.fromName}
                onChange={(e) =>
                  onUpdateDocument((c) => touchDocument({ ...c, fromName: e.target.value }))
                }
              />
            </Field>
            <Field>
              <FieldLabel htmlFor="from-email">From email</FieldLabel>
              <Input
                id="from-email"
                type="email"
                value={document.fromEmail}
                onChange={(e) =>
                  onUpdateDocument((c) => touchDocument({ ...c, fromEmail: e.target.value }))
                }
              />
            </Field>
            <Field>
              <FieldLabel htmlFor="preview-text">Preview text</FieldLabel>
              <Textarea
                id="preview-text"
                rows={2}
                value={document.settings.previewText}
                placeholder="Shown in inbox below the subject line"
                onChange={(e) => setSetting("previewText", e.target.value)}
              />
            </Field>
          </div>
        </ScrollArea>
      </SheetContent>
    </Sheet>
  );
}

"use client";

import * as React from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import { ComputerIcon, EyeIcon, SmartPhone01Icon } from "@hugeicons/core-free-icons";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogHeader,
  DialogPopup,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/coss-dialog";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import { cn } from "@/lib/utils";
import type { PreviewMode } from "./editor-types";

export function PreviewDialog({
  compiled,
}: {
  compiled: { html: string; text: string };
}) {
  const [mode, setMode] = React.useState<PreviewMode>("desktop");

  return (
    <Dialog>
      {/* Base UI trigger composes via render, not Radix asChild. */}
      <DialogTrigger render={<Button variant="outline" size="sm" />}>
        <HugeiconsIcon icon={EyeIcon} strokeWidth={2} data-icon="inline-start" />
        Preview
      </DialogTrigger>
      <DialogPopup className="h-[90vh] sm:max-w-4xl">
        <DialogHeader>
          <DialogTitle>Email preview</DialogTitle>
        </DialogHeader>
        <div className="min-h-0 flex-1 px-6 pb-6">
          <PreviewPane html={compiled.html} mode={mode} onModeChange={setMode} />
        </div>
      </DialogPopup>
    </Dialog>
  );
}

function PreviewPane({
  html,
  mode,
  onModeChange,
}: {
  html: string;
  mode: PreviewMode;
  onModeChange: (m: PreviewMode) => void;
}) {
  const iframeRef = React.useRef<HTMLIFrameElement>(null);
  const [iframeHeight, setIframeHeight] = React.useState(620);

  const previewHtml = React.useMemo(() => {
    if (html.includes("<head>")) return html.replace("<head>", '<head><base href="/">');
    return `<base href="/">${html}`;
  }, [html]);

  const measureIframe = React.useCallback(() => {
    try {
      const doc = iframeRef.current?.contentDocument;
      const h = Math.max(
        doc?.documentElement.scrollHeight ?? 0,
        doc?.body.scrollHeight ?? 0,
      );
      if (h > 0) setIframeHeight(Math.max(620, h));
    } catch {
      setIframeHeight(620);
    }
  }, []);

  React.useEffect(() => {
    const t = window.setTimeout(measureIframe, 50);
    return () => window.clearTimeout(t);
  }, [previewHtml, measureIframe]);

  return (
    <div className="flex h-full min-h-0 flex-col">
      <div className="flex items-center gap-2 border-b px-4 py-2.5">
        <ToggleGroup
          type="single"
          value={mode}
          onValueChange={(v) => { if (v) onModeChange(v as PreviewMode); }}
          variant="outline"
        >
          <ToggleGroupItem value="desktop">
            <HugeiconsIcon icon={ComputerIcon} strokeWidth={2} data-icon="inline-start" />
            Desktop
          </ToggleGroupItem>
          <ToggleGroupItem value="mobile">
            <HugeiconsIcon icon={SmartPhone01Icon} strokeWidth={2} data-icon="inline-start" />
            Mobile
          </ToggleGroupItem>
        </ToggleGroup>
        <Badge variant="outline" className="ml-auto text-xs">
          Live preview
        </Badge>
      </div>

      <div className="min-h-0 flex-1 overflow-auto bg-zinc-100 p-4">
        <div
          className={cn(
            "mx-auto overflow-hidden rounded-xl border bg-white shadow-md transition-[max-width] duration-300",
            mode === "mobile" ? "max-w-[390px]" : "max-w-[720px]",
          )}
        >
          <div className="border-b bg-white px-4 py-3">
            <div className="flex items-center gap-2.5">
              <div className="flex size-8 items-center justify-center rounded-full bg-zinc-900 text-xs font-bold text-white">
                C
              </div>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-semibold">Newsletter</p>
                <p className="truncate text-xs text-muted-foreground">
                  newsletter@example.com
                </p>
              </div>
            </div>
          </div>
          <div className="bg-zinc-100 p-3">
            <iframe
              ref={iframeRef}
              title="Email preview"
              srcDoc={previewHtml}
              scrolling="no"
              sandbox="allow-same-origin"
              onLoad={measureIframe}
              className="w-full rounded-lg border bg-white shadow-sm"
              style={{ height: iframeHeight }}
            />
          </div>
        </div>
      </div>
    </div>
  );
}

const SCRIPT_TAG_RE = /<script\b[\s\S]*?<\/script>/gi;
const OPEN_SCRIPT_TAG_RE = /<script\b[^>]*>/gi;
const EVENT_HANDLER_RE = /\son\w+=(["']).*?\1/gi;
const BARE_EVENT_HANDLER_RE = /\son\w+=[^\s>]+/gi;
const JS_URL_RE = /\s(href|src)=(["'])\s*javascript:[\s\S]*?\2/gi;

export function sanitizePreviewHtml(html: string): string {
  return html
    .replace(SCRIPT_TAG_RE, "")
    .replace(OPEN_SCRIPT_TAG_RE, "")
    .replace(EVENT_HANDLER_RE, "")
    .replace(BARE_EVENT_HANDLER_RE, "")
    .replace(JS_URL_RE, "");
}

export function previewHtml(html: string) {
  return { __html: sanitizePreviewHtml(html) };
}

"use client";

import { HugeiconsIcon } from "@hugeicons/react";
import { cn } from "@/lib/utils";

export function NavButton({
  icon,
  label,
  active,
  onClick,
  onHover,
}: {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  icon: any;
  label: string;
  active: boolean;
  onClick: () => void;
  onHover?: () => void;
}) {
  return (
    <button
      onClick={onClick}
      onMouseEnter={onHover}
      onFocus={onHover}
      className={cn(
        "flex w-11 flex-col items-center gap-1 rounded-xl px-1 py-2.5 text-[9px] font-semibold uppercase tracking-wide leading-none select-none",
        "transition-[background-color,color,transform] duration-150 ease-out active:scale-[0.93]",
        active
          ? "bg-primary/10 text-primary"
          : "text-muted-foreground hover:bg-accent hover:text-foreground",
      )}
    >
      <HugeiconsIcon
        icon={icon}
        strokeWidth={active ? 2.5 : 1.75}
        className="size-[18px]"
      />
      {label}
    </button>
  );
}
